impl<A:OriginalArtifactAppBirth,M:SpaceMember+MemberFactory+'static> Drop for OriginalArtifactInstanceAdmission<A,M>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original native instance admission must retain every source until handoff or paid closure");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.sources);ManuallyDrop::drop(&mut self.candidate);}}}}

